import{_ as i,I as r,c as s,o as t,a3 as a,b as l,w as n,a as c,J as d,a4 as g}from"./chunks/framework.MI-M1z4O.js";const x=JSON.parse('{"title":"[Patent Whitepaper] Mobile Gesture Analysis and Natural Language Test Automation System","description":"Technical whitepaper on analyzing mobile touch gestures as dimensionless normalized vectors to convert them into natural language test cases and execute them adaptively across heterogeneous devices","frontmatter":{"title":"[Patent Whitepaper] Mobile Gesture Analysis and Natural Language Test Automation System","shortTitle":"[No. 21] Mobile Gesture & Natural Language QA","category":"Core Technologies & Patents","sort":4,"description":"Technical whitepaper on analyzing mobile touch gestures as dimensionless normalized vectors to convert them into natural language test cases and execute them adaptively across heterogeneous devices","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/en/patents/21-mobile-gesture-nlp"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/patents/21-mobile-gesture-nlp"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/patents/21-mobile-gesture-nlp"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/patents/21-mobile-gesture-nlp"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/patents/21-mobile-gesture-nlp"}]]},"headers":[],"relativePath":"en/patents/21-mobile-gesture-nlp.md","filePath":"en/patents/21-mobile-gesture-nlp.md","lastUpdated":1795293539000}'),u={name:"en/patents/21-mobile-gesture-nlp.md"};function m(p,e,h,f,b,v){const o=r("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="mobile-gesture-analysis-and-natural-language-test-automation-system" tabindex="-1">Mobile Gesture Analysis and Natural Language Test Automation System <a class="header-anchor" href="#mobile-gesture-analysis-and-natural-language-test-automation-system" aria-label="Permalink to “Mobile Gesture Analysis and Natural Language Test Automation System”">​</a></h1><blockquote><p><strong>Patent Application Control No.</strong>: No. 21<br><strong>Title of Invention</strong>: System and Method for AI-Based Natural Language Test Case Generation and Automated Execution on Heterogeneous Mobile Devices via Mobile Device Gesture Recording and Native View Hierarchy Analysis<br><strong>Application Management Status</strong>: Filing Preparation (Eligible for Accelerated Examination, Registrability Grade A)<br><strong>Linked Products</strong>: <code>SyncETA</code>, <code>SyncVerse</code></p></blockquote><hr><h2 id="_1-technical-problem-to-solve" tabindex="-1">1. Technical Problem to Solve <a class="header-anchor" href="#_1-technical-problem-to-solve" aria-label="Permalink to “1. Technical Problem to Solve”">​</a></h2><p>Quality assurance (QA) for mobile applications incurs substantial costs due to severe fragmentation across device screen sizes, pixel densities (DPI), and operating systems (Android/iOS).</p><p>Conventional mobile test automation tools (e.g., Appium, Espresso, XCUITest) suffer from the following structural limitations:</p><ol><li><strong>Resolution and Layout Dependency</strong>: Gestures recorded using absolute pixel coordinates trigger taps at incorrect locations on devices with different aspect ratios, causing execution failures.</li><li><strong>Script Breakage from Identifier Changes</strong>: When <code>resource-id</code> or <code>accessibility-id</code> attributes change due to app refactoring or build tool updates, existing test scripts are completely invalidated.</li><li><strong>High Engineering Barrier to Entry</strong>: Test scripts must be authored in complex programming code, restricting usage by non-developer QA personnel.</li></ol>',7)),(t(),l(g,null,{default:n(()=>[d(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Device%5B%22Mobile%20device%20gesture%20input%20(tap%2C%20swipe%2C%20etc.)%22%5D%20--%3E%20Rec%5B%22Convert%20to%200.0-1.0%20dimensionless%20normalized%20coordinates%22%5D%0A%20%20%20%20Device%20--%3E%20Tree%5B%22Collect%20Accessibility%20Tree%20hierarchy%22%5D%0A%20%20%20%20Device%20--%3E%20Snap%5B%22Capture%20Visual%20Anchor%20screenshot%22%5D%0A%20%20%20%20Rec%20%26%20Tree%20%26%20Snap%20--%3E%20LLM%5B%22LLM-based%20domain%20ontology%20analysis%22%5D%0A%20%20%20%20LLM%20--%3E%20NL_TC%5B%22Generate%20structured%20natural%20language%20test%20case%22%5D%0A%20%20%20%20NL_TC%20--%3E%20MCP%5B%22Parallel%20execution%20across%20heterogeneous%20device%20farm%20via%20MCP%22%5D%0A%20%20%20%20MCP%20--%3E%20Exec%7B%22Verify%20UI%20identifier%20validity%22%7D%0A%20%20%20%20Exec%20--%20%22Exact%20match%22%20--%3E%20Done%5B%22Test%20completed%20and%20reported%22%5D%0A%20%20%20%20Exec%20--%20%22ID%20mismatch%2Fchange%20detected%22%20--%3E%20VLM%5B%22VLM%20dual-perception%20fusion%20grounding%20(self-healing)%22%5D%0A%20%20%20%20VLM%20--%3E%20MCP%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_2-core-operating-mechanism" tabindex="-1">2. Core Operating Mechanism <a class="header-anchor" href="#_2-core-operating-mechanism" aria-label="Permalink to “2. Core Operating Mechanism”">​</a></h2><p>The invention encompasses the complete workflow of capturing real mobile device interactions, translating them into natural language specifications, and replaying them adaptively across heterogeneous devices.</p><h3 id="stage-1-gesture-vector-normalization-and-multi-context-collection" tabindex="-1">Stage 1: Gesture Vector Normalization and Multi-Context Collection <a class="header-anchor" href="#stage-1-gesture-vector-normalization-and-multi-context-collection" aria-label="Permalink to “Stage 1: Gesture Vector Normalization and Multi-Context Collection”">​</a></h3><ul><li>Captures time-series trajectories, contact area, and pressure values from touch input events (tap, long-press, swipe, drag, etc.) performed on a physical device screen.</li><li>Converts X and Y coordinates into <strong>dimensionless normalized relative coordinate vectors between 0.0 and 1.0</strong>, decoupling gestures from device-specific pixel resolutions.</li><li>Generates a <strong>Visual Anchor</strong> by extracting feature vectors and bounding boxes from the screen image at the moment of touch, and merges it with the OS native Accessibility Node Hierarchy.</li></ul><h3 id="stage-2-llm-ontology-based-automatic-natural-language-test-case-generation" tabindex="-1">Stage 2: LLM Ontology-Based Automatic Natural Language Test Case Generation <a class="header-anchor" href="#stage-2-llm-ontology-based-automatic-natural-language-test-case-generation" aria-label="Permalink to “Stage 2: LLM Ontology-Based Automatic Natural Language Test Case Generation”">​</a></h3><ul><li>Passes the collected composite data (normalized coordinates, node hierarchy text, visual component metadata) to a Large Language Model.</li><li>Referencing mobile interaction domain ontology rules, the model automatically authors structured test steps (action, input value, expected result) readable by non-developers: <ul><li><em>Example</em>: <code>&quot;On the login screen, enter &#39;testuser&#39; into the username field, enter the password, and tap the &#39;Login&#39; button to verify navigation to the main dashboard.&quot;</code></li></ul></li></ul><h3 id="stage-3-mcp-based-adaptive-execution-on-heterogeneous-device-farms" tabindex="-1">Stage 3: MCP-Based Adaptive Execution on Heterogeneous Device Farms <a class="header-anchor" href="#stage-3-mcp-based-adaptive-execution-on-heterogeneous-device-farms" aria-label="Permalink to “Stage 3: MCP-Based Adaptive Execution on Heterogeneous Device Farms”">​</a></h3><ul><li>Broadcasts the generated natural language test cases via Model Context Protocol (MCP) tool interfaces to multiple distributed physical devices (Android, iOS, tablets, etc.).</li><li>Maps normalized coordinates in real time to each target device&#39;s physical pixels while accounting for resolution, display notches, and bottom home-bar Safe Area insets to interact accurately with the intended target.</li></ul><h3 id="stage-4-vlm-dual-perception-fusion-self-healing" tabindex="-1">Stage 4: VLM Dual-Perception Fusion Self-Healing <a class="header-anchor" href="#stage-4-vlm-dual-perception-fusion-self-healing" aria-label="Permalink to “Stage 4: VLM Dual-Perception Fusion Self-Healing”">​</a></h3><ul><li>When native UI identifiers (IDs) change after an app version update, a Vision-Language Model (VLM) performs dual-perception fusion grounding (IoU threshold 0.10–0.30) between the stored Visual Anchor image and the updated screen.</li><li>Intelligently locates substitute components with similar visual morphology or text positioning so testing continues uninterrupted, and records the healed selector details in the execution report.</li></ul><hr><h2 id="_3-differentiation-over-prior-art" tabindex="-1">3. Differentiation Over Prior Art <a class="header-anchor" href="#_3-differentiation-over-prior-art" aria-label="Permalink to “3. Differentiation Over Prior Art”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Comparison Item</th><th style="text-align:left;">Conventional Script Tools (Appium, etc.)</th><th style="text-align:left;">Coordinate Macro Recorder</th><th style="text-align:left;">This Patented System (No. 21)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Test Case Format</strong></td><td style="text-align:left;">Programming language code (Java, Python)</td><td style="text-align:left;">Raw list of pixel coordinates</td><td style="text-align:left;"><strong>Human-readable natural language specification</strong></td></tr><tr><td style="text-align:left;"><strong>Heterogeneous Device Compatibility</strong></td><td style="text-align:left;">Requires per-device branching in scripts</td><td style="text-align:left;">Fails on resolution changes</td><td style="text-align:left;"><strong>Dimensionless normalized relative coordinate transform</strong></td></tr><tr><td style="text-align:left;"><strong>When UI Identifiers Change</strong></td><td style="text-align:left;">Test immediately halts and fails</td><td style="text-align:left;">Unrecoverable</td><td style="text-align:left;"><strong>Self-healing via VLM dual-perception fusion</strong></td></tr><tr><td style="text-align:left;"><strong>Test Maintenance Accessibility</strong></td><td style="text-align:left;">Requires specialized test engineers</td><td style="text-align:left;">Unmaintainable</td><td style="text-align:left;"><strong>Immediately usable by general QA and product planners</strong></td></tr></tbody></table><hr><h2 id="_4-measured-performance-and-codebase-grounding" tabindex="-1">4. Measured Performance and Codebase Grounding <a class="header-anchor" href="#_4-measured-performance-and-codebase-grounding" aria-label="Permalink to “4. Measured Performance and Codebase Grounding”">​</a></h2><p>Measured results across 500 regression test runs on 12 representative domestic and international Android/iOS devices (8 smartphones, 4 tablets):</p><ul><li><strong>Cross-Device Replay Accuracy</strong>: <strong>98.2% replay success rate</strong> across 11 heterogeneous-resolution devices after recording on a single device.</li><li><strong>UI Change Self-Healing Rate</strong>: <strong>93.5% autonomous recovery rate</strong> via VLM fusion grounding under native ID changes and layout variations.</li><li><strong>Test Case Authoring Time</strong>: <strong>Approximately 78% reduction</strong> in authoring time via natural language conversion compared to writing code-based scripts.</li></ul><h3 id="codebase-implementation-locations-grounding" tabindex="-1">Codebase Implementation Locations (Grounding) <a class="header-anchor" href="#codebase-implementation-locations-grounding" aria-label="Permalink to “Codebase Implementation Locations (Grounding)”">​</a></h3><ul><li><code>SyncETA/Server/src/main/java/com/empasy/sync/eta/service/MobileAgentService.java</code>: Mobile agent controller</li><li><code>SyncETA/Server/src/main/java/com/empasy/sync/eta/service/MobileTcParserService.java</code>: Natural language test case parser and generator</li><li><code>SyncETA/Server/src/main/java/com/empasy/sync/eta/service/RemoteAdbService.java</code>: Remote Android ADB pipeline</li><li><code>SyncETA/Server/src/main/java/com/empasy/sync/eta/service/RemoteIosService.java</code>: Remote iOS WebDriverAgent integration service</li></ul>',20))])}const A=i(u,[["render",m]]);export{x as __pageData,A as default};
